file_path = 'src/data/kpsea-sst-hre-2025.js'
with open(file_path, 'r', encoding='utf-8') as f:
    content = f.read()

match = re.search(r'export const \w+ = (\{.*\});?\s*$', content, re.DOTALL)
if not match:
    print("Could not parse file")
    exit(1)
    
data = json.loads(match.group(1))

for q in data["sectionA"]:
    if q["id"] in explanations:
        q["explanation"] = explanations[q["id"]]

new_content = "export const kpseaSstHre2025 = " + json.dumps(data, indent=2) + ";\n"
with open(file_path, 'w', encoding='utf-8') as f:
    f.write(new_content)

print("Batch 4 (HRE Q41-Q50) updated successfully.")
